        if (ch == '`' && !isInCodeBlock) {
            isInCodeBlock = true;
            htmlStream << "<pre>";
        } else if (ch == '`' && isInCodeBlock) {
            isInCodeBlock = false;
            htmlStream << "</pre>";
        } else {
            if (isInCodeBlock) {
                currentCode += ch;
            } else {
                htmlStream << ch;
            }
        }
    }

    htmlStream << "<br>\n";

    // Bloques de texto
